namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications =
    [
        new(0, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
    ];

    public NotificationService()
    {
        // Seed a few initial notifications.
        _notifications =
        [
            new(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
            new(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
            new(_nextId++, "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-5)),
        ];
    }

    /// <summary>Returns all notifications created after the given timestamp.</summary>
    public Task<List<Notification>> GetNotificationsAsync(DateTime? since = null)
    {
        lock (_lock)
        {
            var result = since is null
                ? _notifications.OrderByDescending(n => n.Timestamp).ToList()
                : _notifications.Where(n => n.Timestamp > since).OrderByDescending(n => n.Timestamp).ToList();
            return Task.FromResult(result);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Call this from a background service or let the polling page call it.
    /// </summary>
    public Notification SimulateIncoming()
    {
        var messages = new[]
        {
            "Deployment succeeded.",
            "New comment on your PR.",
            "Build #42 failed.",
            "You have a new follower.",
            "Server CPU is above 90%.",
            "Weekly report is ready.",
        };

        lock (_lock)
        {
            var n = new Notification(
                _nextId++,
                messages[Random.Shared.Next(messages.Length)],
                DateTime.UtcNow);
            _notifications.Add(n);
            return n;
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationsApp.Services.Notification>? PersistedNotifications { get; set; }

    private List<NotificationsApp.Services.Notification> notifications = new();
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state or load fresh — never double-fetch.
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationSvc.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only starts after the page is interactive — never during prerender.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            // Simulate a new notification arriving on the server side.
            NotificationSvc.SimulateIncoming();

            var latest = notifications.Count > 0
                ? notifications.Max(n => n.Timestamp)
                : DateTime.MinValue;

            var newItems = await NotificationSvc.GetNotificationsAsync(since: latest);

            if (newItems.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications.InsertRange(0, newItems);
                    PersistedNotifications = notifications;
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

