+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in notifications)
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <div>@n.Message</div>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    [PersistentState]
+    public List<NotificationsApp.Services.Notification>? PersistedNotifications { get; set; }
+
+    private List<NotificationsApp.Services.Notification> notifications = new();
+    private CancellationTokenSource? _cts;
+
+    protected override async Task OnInitializedAsync()
+    {
+        // Restore from prerender state or load fresh — never double-fetch.
+        if (PersistedNotifications is not null)
+        {
+            notifications = PersistedNotifications;
+        }
+        else
+        {
+            notifications = await NotificationSvc.GetNotificationsAsync();
+            PersistedNotifications = notifications;
+        }
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // Only starts after the page is interactive — never during prerender.
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);
+
+            // Simulate a new notification arriving on the server side.
+            NotificationSvc.SimulateIncoming();
+
+            var latest = notifications.Count > 0
+                ? notifications.Max(n => n.Timestamp)
+                : DateTime.MinValue;
+
+            var newItems = await NotificationSvc.GetNotificationsAsync(since: latest);
+
+            if (newItems.Count > 0)
+            {
+                await InvokeAsync(() =>
+                {
+                    notifications.InsertRange(0, newItems);
+                    PersistedNotifications = notifications;
+                    StateHasChanged();
+                });
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
